storytimeAudio.ge = storytimeAudio.gn;

export function getStorytimeAudioUrl(bookAbbrev, chapter) {
  if (!bookAbbrev || chapter == null) return null;
  const book = storytimeAudio[bookAbbrev];
  if (!book) return null;
  return book[chapter] || null;
}

export default storytimeAudio;
